-- Product-specific, single-use 30-day Product Pro codes.
ALTER TABLE sw_plan_redemption_codes ADD COLUMN duration_days INTEGER CHECK (duration_days IS NULL OR (duration_days > 0 AND duration_days <= 3660));

-- Product plans are independent; legacy bundle triggers must not copy future grants.
DROP TRIGGER IF EXISTS sw_product_pro_bundle_after_insert;
DROP TRIGGER IF EXISTS sw_product_pro_bundle_after_update;

